export default async function sendIssueAlerts({ notifications, chatId }, context) {
  const sent = [];
  for (const { text } of notifications) sent.push(await context.actions.telegram.send_message({ chatId, text, parseMode: 'HTML' }));
  return { sent, count: sent.length };
}
